const cfg = $('Configuration').first().json;
const stunden = Number(cfg.staleHours) || 24;

const workflows = ($('Get workflows').first().json.data || []).filter((w) => w.active && !w.isArchived);
const executions = $('Get executions').first().json.data || [];

// Letzter Lauf je Workflow. Das Fenster reicht nur so weit zurueck wie limit=250 —
// bei sehr vielen Ausfuehrungen kann ein stiller Workflow dadurch uebersehen werden.
const zuletzt = new Map();
for (const e of executions) {
  const id = String(e.workflowId);
  const t = new Date(e.startedAt || e.createdAt).getTime();
  if (!Number.isFinite(t)) continue;
  if (!zuletzt.has(id) || t > zuletzt.get(id)) zuletzt.set(id, t);
}

const jetzt = Date.now();
const grenze = jetzt - stunden * 3600 * 1000;
const still = [];

for (const w of workflows) {
  const t = zuletzt.get(String(w.id));
  if (t === undefined) {
    still.push({ workflow: w.name, workflowId: w.id, lastRun: null, hoursSilent: null, note: 'no execution in the window' });
  } else if (t < grenze) {
    still.push({ workflow: w.name, workflowId: w.id, lastRun: new Date(t).toISOString(), hoursSilent: Math.round((jetzt - t) / 3600000), note: 'active but stalled' });
  }
}

if (still.length === 0) return [{ json: { silent: 0, activeChecked: workflows.length } }];
return still.map((json) => ({ json }));
